    const Real ref_curvature_cse_3 = L_r*ref_curvature_cse_2;
    const Real ref_curvature_cse_4 = B*L;
    const Real ref_curvature_cse_5 = 2*ref_curvature_cse_4;
    const Real ref_curvature_cse_6 = ref_curvature_cse_3*ref_curvature_cse_5;
    const Real ref_curvature_cse_7 = ref_curvature_cse_1*ref_curvature_cse_6;
    const Real ref_curvature_cse_8 = B*X1;
    const Real ref_curvature_cse_9 = ref_curvature_cse_3*ref_curvature_cse_8;
    const Real ref_curvature_cse_10 = L*X1;
    const Real ref_curvature_cse_11 = B_r*ref_curvature_cse_2;
    const Real ref_curvature_cse_12 = ref_curvature_cse_10*ref_curvature_cse_11;
