    const Real ref_curvature_cse_21 = ref_curvature_cse_15 + ref_curvature_cse_20 + ref_curvature_cse_7;
    const Real ref_curvature_cse_22 = (1.0/2.0)*ref_curvature_cse_0;
    const Real ref_curvature_cse_23 = ref_curvature_cse_21*ref_curvature_cse_22;
    const Real ref_curvature_cse_24 = ref_curvature_cse_0*ref_curvature_cse_7 - ref_curvature_cse_23;
    const Real ref_curvature_cse_25 = 1.0/L;
    const Real ref_curvature_cse_26 = (1.0/2.0)*ref_curvature_cse_25;
    const Real ref_curvature_cse_27 = ref_curvature_cse_26*ref_curvature_cse_8;
    const Real ref_curvature_cse_28 = ref_curvature_cse_24*ref_curvature_cse_27;
    const Real ref_curvature_cse_29 = Kokkos::pow(X0, 2);
